<?php
namespace qqworld_collector\module\cloud_storage; use qqworld_collector\module\cloudStorage2; class caihong extends cloudStorage2 { var $host = ''; var $all_type_allowed = true; public function init() { $this->host = $this->options->cloud_storage_caihong_host; $this->silent_scanning = $this->options->cloud_storage_caihong_silent_scanning; $this->delete_attachment_after_synced = $this->options->cloud_storage_joinmode_enabled ? 0 : $this->options->cloud_storage_caihong_delete_attachment_after_synced; } protected function _httpPostImg($url, $params = array() , $header = array()) { $ch = curl_init(); curl_setopt($ch, CURLOPT_URL, $url); curl_setopt($ch, CURLOPT_RETURNTRANSFER, true); curl_setopt($ch, CURLOPT_TIMEOUT, 500); curl_setopt($ch,CURLOPT_FOLLOWLOCATION,1); curl_setopt($ch, CURLOPT_POST, true); curl_setopt($ch, CURLOPT_POSTFIELDS, $params); $header = array('Content-Type: multipart/form-data'); curl_setopt($ch, CURLOPT_HTTPHEADER, $header); curl_setopt($ch, CURLINFO_HEADER_OUT, true); $response = curl_exec($ch); curl_close($ch); return $response; } public function upload($destination_path, $source_path) { if (!file_exists($source_path) || !filesize($source_path)) return false; $url = $this->host . '/api.php'; $params = array( 'file' => new \CURLFile($source_path) ); $result = $this->_httpPostImg($url, $params); $result = json_decode($result, true); do_action( 'qqworld-collector-log', $this->log_id, 'Caihong:', print_r($result, true) ); if ($result['code'] == 0) { return $result['viewurl'] ? $result['viewurl'] : $result['downurl']; } else { do_action( 'qqworld-collector-log', $this->log_id, 'Caihong failed: ', print_r($result, true) ); } return false; } public function add_could_storage_form($guid) { $this->accessed = $this->is_current; require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage-'.$this->guid.'.php'; } } ?>